"use client";
import { Clock, MessageCircle, Send } from "lucide-react";
import { useWorkspaceQuota } from "@/components/workspace-quota";
import type { QuotaSnapshot } from "@/lib/quota-snapshot";
import { StatCard } from "./StatCard";
export function HistoryStats({
  today,
  queued,
  totalSent,
  replies,
  source,
}: {
  today: number;
  queued: number;
  totalSent: number;
  replies: number;
  source: QuotaSnapshot;
}) {
  const quota = useWorkspaceQuota(source);
  const limit = quota.mode === "gated" ? quota.daily.limit : quota.limit;
  const ratio =
    limit > 0 ? Math.max(0, Math.min(100, (today / limit) * 100)) : 0;
  return (
    <section
      aria-label="History summary"
      className="grid grid-cols-[repeat(3,_minmax(0,_1fr))] gap-4 [@media(max-width:_859px)]:grid-cols-[1fr]"
    >
      <StatCard
        label="Sent today"
        icon={
          <Send
            size={16}
            style={{ color: "var(--h-purple)" }}
            aria-hidden="true"
          />
        }
        tint="var(--workspace-icon-bg, var(--appearance-wash, var(--color-historystats-detail-1)))"
        value={today}
        suffix={
          <span className="text-[var(--h-muted)] text-[18px] font-semibold tracking-[normal]">
            {" "}
            / {limit}
          </span>
        }
        tooltip="Counts emails Gmail accepted today (UTC). Queued emails reserve allowance too."
      >
        <div
          className="h-1.5 rounded-[var(--appearance-radius,_4px)] overflow-hidden [background:var(--h-border)]"
          role="progressbar"
          aria-label="Sent today"
          aria-valuenow={today}
          aria-valuemin={0}
          aria-valuemax={Math.max(limit, today)}
        >
          <div
            className="h-full [background:var(--progress-fill,_linear-gradient(_135deg,_var(--color-history-h-purple-13),_var(--color-history-h-pink-14)))]"
            style={{ width: `${ratio}%` }}
          />
        </div>
        <div className="flex justify-between flex-wrap gap-1.5 mt-[7px] text-[var(--h-muted)] text-[12.5px]">
          {quota.mode === "gated" ? (
            <>
              <span>Daily</span>
              <span>
                {quota.monthly.startsAt
                  ? `${quota.monthly.used} / ${quota.monthly.limit} this month`
                  : "Monthly allowance unavailable"}
              </span>
            </>
          ) : (
            <span>
              {quota.used} / {quota.limit} used or reserved per rolling 24h
            </span>
          )}
        </div>
      </StatCard>
      <StatCard
        label="In queue"
        icon={
          <Clock
            size={16}
            style={{ color: "var(--h-yellow)" }}
            aria-hidden="true"
          />
        }
        tint="var(--color-historystats-detail-2)"
        value={queued}
        tooltip="Sends are normally spaced about 5 seconds apart. Gmail limits may extend waits."
      >
        <div className="flex justify-between flex-wrap gap-1.5 mt-[7px] text-[var(--h-muted)] text-[12.5px]">
          {totalSent} sent in total
        </div>
      </StatCard>
      <StatCard
        label="Replies"
        icon={
          <MessageCircle
            size={16}
            style={{ color: "var(--h-pink)" }}
            aria-hidden="true"
          />
        }
        tint="var(--workspace-icon-bg, var(--appearance-replied-bg, var(--color-historystats-detail-3)))"
        value={replies}
        tooltip="Mailloop never reads your inbox. You mark replies yourself."
      >
        <div className="flex justify-between flex-wrap gap-1.5 mt-[7px] text-[var(--h-muted)] text-[12.5px]">
          Marked manually
        </div>
      </StatCard>
    </section>
  );
}
